let
  root = /home/dylan/src/aos/.worktrees/codex/bazel-integration-722;
  inputs = import ./aos-cli-cargo-baselines.nix;
  inherit (inputs) pkgs nativeLibraries nativeTools cargoSetup;
in pkgs.mkDerivation {
  pname = "aos-bazel-aos-cli-production-cargo-baseline";
  version = "1";
  src = import (root + "/pkgs/tools/aos/_workspace-source.nix") {inherit (pkgs) lib;};
  buildDeps = [pkgs.rust pkgs.sed pkgs.python3] ++ nativeTools;
  runtimeDeps = nativeLibraries;
  sharedBuildCache = false;
  dontStrip = true;
  dontPatchELF = true;
  dontNukeRefs = true;
  phases = [{
    name = "compile";
    script = ''
      cp -R "$src" source
      chmod -R u+w source
      cd source
      export CARGO_HOME="$TMPDIR/cargo" CARGO_TARGET_DIR="$TMPDIR/target"
      mkdir -p "$CARGO_HOME" .cargo "$out/bin"
      sed 's|@vendor@|${pkgs.aos.passthru.cargoDeps}|g' \
        ${pkgs.aos.passthru.cargoDeps}/.cargo/config.toml > .cargo/config.toml
      ${cargoSetup}
      cargo build --release --frozen --offline --manifest-path crates/Cargo.toml \
        -p aos-cli -p aos-package-manager -p aos-image-finalizer --bins \
        --features aos-cli/release-fleet-fixture --jobs "$NIX_BUILD_CORES" \
        --message-format=json > "$out/cargo-messages.jsonl"
      ${pkgs.python3}/bin/python3 - "$out" <<'PY'
      import json
      from pathlib import Path
      import shutil
      import sys

      output = Path(sys.argv[1])
      artifacts = []
      for line in (output / "cargo-messages.jsonl").read_text().splitlines():
          event = json.loads(line)
          if (event.get("reason") == "compiler-artifact" and event.get("executable")
                  and event["target"]["kind"] == ["bin"]):
              source = Path(event["executable"])
              target = output / "bin" / source.name
              if target.exists():
                  raise ValueError(f"duplicate production binary: {source.name}")
              shutil.copy2(source, target)
              artifacts.append(event["target"]["name"])
      (output / "binaries.json").write_text(json.dumps(sorted(artifacts), indent=2) + "\n")
      PY
    '';
  }];
}

