let
  root = /home/dylan/src/aos/.worktrees/codex/bazel-integration-722;
  pkgs = (import root {}).pkgs;
  inputs = import (root + "/tests/build/_bazel-registry-native-inputs.nix") {inherit pkgs;};
  console = builtins.storePath /nix/store/3qbx40f2v5x67isav0cvvxd1ssq4ka88-aos-bazel-console-assets-1;
  nativeLibraries = inputs.nativeLibraries ++ [pkgs.sqlite];
  nativeTools = inputs.nativeTools ++ [pkgs.alejandra pkgs.mtools pkgs.tpm2-tools pkgs.util-linux pkgs.aos-landlock];
  cargoSetup = inputs.cargoSetup + ''
    export LIBSQLITE3_SYS_USE_PKG_CONFIG=1
    export AOS_HUB_CONSOLE_JS="${console}/hub-console.js"
    export AOS_HUB_CONSOLE_WASM="${console}/hub-console_bg.wasm"
    export AOS_HUB_CONSOLE_CSS="${console}/hub-console.css"
    export AOS_MCOPY="${pkgs.mtools}/bin/mcopy"
    export AOS_LANDLOCK_WRAPPER="${pkgs.aos-landlock}/bin/aos-landlock"
    export AOS_UNSHARE="${pkgs.util-linux}/bin/unshare"
    export AOS_PRLIMIT="${pkgs.util-linux}/bin/prlimit"
    export AOS_TPM2_CREATEEK="${pkgs.tpm2-tools}/bin/tpm2_createek"
    export AOS_TPM2_CREATEAK="${pkgs.tpm2-tools}/bin/tpm2_createak"
    export AOS_TPM2_READPUBLIC="${pkgs.tpm2-tools}/bin/tpm2_readpublic"
    export AOS_TPM2_QUOTE="${pkgs.tpm2-tools}/bin/tpm2_quote"
    export AOS_TPM2_PCRREAD="${pkgs.tpm2-tools}/bin/tpm2_pcrread"
    export AOS_TPM2_PCREXTEND="${pkgs.tpm2-tools}/bin/tpm2_pcrextend"
    export AOS_TPM2_CHECKQUOTE="${pkgs.tpm2-tools}/bin/tpm2_checkquote"
    export AOS_TPM2_FLUSHCONTEXT="${pkgs.tpm2-tools}/bin/tpm2_flushcontext"
    export RUST_TEST_THREADS="$NIX_BUILD_CORES"
  '';
  ordinaryOracle = flags: suffix: import (root + "/tests/build/_bazel-cargo-oracle.nix") {
    inherit pkgs nativeLibraries nativeTools cargoSetup;
    cargoSource = import (root + "/pkgs/tools/aos/_workspace-source.nix") {inherit (pkgs) lib; includeIntegrationInputs = true;};
    pname = "aos-bazel-aos-cli-" + suffix + "cargo-baseline";
    packages = ["aos-cli"];
    cargoFlags = flags;
  };
  oracle = flags: suffix:
    (ordinaryOracle flags suffix).overrideAttrs (old: {
      pname = old.pname + "-capture";
      phases = map (phase: if phase.name != "compare" then phase else phase // {
        script = let
          before = "--jobs \"$NIX_BUILD_CORES\" > \"$out/cargo-tests.log\" 2>&1 || {\n  tail -n 100 \"$out/cargo-tests.log\"\n  exit 1\n}";
          after = "--jobs \"$NIX_BUILD_CORES\" --no-fail-fast > \"$out/cargo-tests.log\" 2>&1 && status=0 || status=$?\n          printf '%s' \"$status\" > \"$out/cargo-test-exit-status\"";
          changed = builtins.replaceStrings [before] [after] phase.script;
        in assert changed != phase.script; changed;
      }) old.phases;
    });
in {
  inherit pkgs nativeLibraries nativeTools cargoSetup;
  default = oracle [] "";
  fleet = oracle ["--features" "release-fleet-fixture"] "fleet-";
  builds = [ (oracle [] "") (oracle ["--features" "release-fleet-fixture"] "fleet-") ];
}
